  test('should return empty array when input is empty', () => {
    expect(bubbleSort([])).toEqual([]);
  });

  test('should return single element array', () => {
    expect(bubbleSort([5])).toEqual([5]);
  });

  test('should sort already sorted array', () => {
    expect(bubbleSort([1, 2, 3, 4])).toEqual([1, 2, 3, 4]);
  });

  test('should sort reverse sorted array', () => {
    expect(bubbleSort([4, 3, 2, 1])).toEqual([1, 2, 3, 4]);
  });

  test('should handle duplicates', () => {
    expect(bubbleSort([3, 2, 2, 1])).toEqual([1, 2, 2, 3]);
  });

  test('should handle all duplicates', () => {
    expect(bubbleSort([5, 5, 5])).toEqual([5, 5, 5]);
  });

  test('should sort mixed elements', () => {
    expect(bubbleSort([5, 3, 8, 4, 2])).toEqual([2, 3, 4, 5, 8]);
  });
});
```

