```python
def get_variable_type(var):
    if isinstance(var, list):
        if any(isinstance(item, list) for item in var):
            return "Nested list"
        return "List"
    elif isinstance(var, dict):
        if any(isinstance(value, dict) for value in var.values()):
            return "Nested dictionary"
        return "Dictionary"
    elif isinstance(var, str):
        return "String"
    elif isinstance(var, int):
        return "Integer"
    elif isinstance(var, float):
        return "Float"
    elif isinstance(var, bool):
        return "Boolean"
    elif isinstance(var, tuple):
        return "Tuple"
    elif isinstance(var, set):
        return "Set"
    elif isinstance(var, frozenset):
        return "Frozen set"
    elif isinstance(var, type):
        return "Class"
    elif isinstance(var, module):
        return "Module"
    else:
        return "Custom class"
```

You can use this function to get the type of any variable, including nested lists and dictionaries, as well as built-in classes and modules. Here are some examples:

```python
# Built-in classes
print(get_variable_type("Hello"))  # Output: String
print(get_variable_type(42))  # Output: Integer
print(get_variable_type([1, 2, 3]))  # Output: List
print(get_variable_type({"name": "John", "age": 25}))  # Output: Dictionary

# Nested variables
print(get_variable_type([[1, 2], [3, 4]]))  # Output: Nested list
print(get_variable_type({"person": {"name": "John", "age": 25}}))  # Output: Nested dictionary

# Custom classes and modules
class MyClass:
    pass

my_variable = MyClass()
print(get_variable_type(my_variable))  # Output: Custom class

import math
print(get_variable_type(math))  # Output: Module
```

