To clean up the JSON data and ensure consistent data types, we need to recursively traverse the JSON object and convert the age field to a string data type. We also need to handle cases where the hobbies field contains null values or objects with missing firstname or lastname fields.

Here's a Python solution that handles nested JSON objects and arrays of arbitrary depth:

```python
import json

def clean_json(json_data):
    if isinstance(json_data, dict):
        cleaned_data = {}
        for key, value in json_data.items():
            cleaned_data[key] = clean_json(value)
        return cleaned_data
    elif isinstance(json_data, list):
        cleaned_data = []
        for item in json_data:
            cleaned_data.append(clean_json(item))
        return cleaned_data
    elif isinstance(json_data, int):
        return str(json_data)
    elif json_data is None:
        return None
    elif isinstance(json_data, str):
        return json_data
    else:
        return None  # Handle unrecognized data types

# Sample JSON data
data = '''
{
  "name": "John Doe",
  "age": 30,
  "hobbies": [
    "reading",
    null,
    {
      "name": "gardening",
      "participants": [
        {
          "firstname": "Alice",
          "lastname": "Smith"
        },
        {
          "firstname": null,
          "lastname": "Johnson"
        }
      ]
    }
  ]
}
'''

# Parse the JSON data
parsed_data = json.loads(data)

# Clean up the JSON data
cleaned_data = clean_json(parsed_data)

# Convert back to JSON string
cleaned_data_str = json.dumps(cleaned_data)

print(cleaned_data_str)
```

