```python
import random

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

primes = []
while len(primes) < 10:
    num = random.randint(0, 1000)
    if num % 2 != 0 and num % 3 != 0 and num % 5 != 0 and num % 7 != 0 and is_prime(num):
        primes.append(num)

print(primes)
