# Base plugin class
class Plugin_v1:
    @staticmethod
    def capabilities() -> List[str]:
        return [CAPABILITY_DUMMY]

    @staticmethod
    def get_format() -> (str, str):
        return ('', '')

    @staticmethod
    def get_file_extension(knowledge_set):
